protected double calculateNumericalVariance() {
    final double sh = getShape();
    final double sc = getScale();
    final double mn = getNumericalMean();

    return (sc * sc) * FastMath.exp(Gamma.logGamma(1 + (2 / sh))) -
           (mn * mn);
}

